// Economic Policy Sandbox: versioned, data-only definitions shared by the authoritative room server and the
// workstation interface. The server validates every plan against these definitions; the browser only uses
// them to draw forms. Policies are named, versioned rules executed by server code, never user-supplied code.

export const EXPERIMENT_SCHEMA='campos.policy-experiment/1';
export const EXPORT_SCHEMA='campos.policy-experiment-export/1';
export const ENGINE_VERSION='policy-sandbox-engine/1';
export const SANDBOX_LIMITS=Object.freeze({
 minPolicies:2,maxPolicies:4,maxReplications:8,maxSweepValues:4,maxRuns:64,maxSeed:0xffffffff,labelLength:80,weightMax:10,
 // Execution and storage budgets, enforced by the server (see docs/ECONOMIC-LAB.md).
 timeoutMs:5000,memoryMb:64,recordBytes:2_000_000,experimentsPerPrincipal:40,bytesPerPrincipal:24_000_000,totalBytes:256_000_000,
});
const UNITS='simulation units';
const int=(id,label,min,max,value,description,extra={})=>({id,label,type:'int',min,max,step:1,default:value,description,...extra});
const bool=(id,label,value,description)=>({id,label,type:'bool',default:value,description});
const metric=(id,label,category,unit,direction,kind,definition,denominator,population,extra={})=>({id,label,category,unit,direction,kind,definition,denominator,population,missing:kind==='ratio'||kind==='mean'?'Reported as insufficient evidence when the denominator is zero.':'Always defined; zero when nothing occurred.',...extra});

