export const policyKey=(id,version)=>`${id}@${version}`;
export const latestPolicy=id=>Object.values(SANDBOX_POLICIES).filter(p=>p.id===id).sort((a,b)=>b.version-a.version)[0]??null;
export const scenarioFor=(id,version)=>SANDBOX_SCENARIOS[`${id}@${version}`]??null;
export const domainScenario=domain=>{const d=DOMAINS.find(d=>d.id===domain);return d?scenarioFor(d.scenario,d.version):null;};
export const defaults=params=>Object.fromEntries(params.map(p=>[p.id,p.default]));
export const metricDef=(scenario,id,group=false)=>(group?scenario.groupMetrics:scenario.metrics).find(m=>m.id===id)??null;
/** A JSON-safe copy of a definition (drops nothing executable because definitions contain only data). */
export const snapshotDefinition=d=>JSON.parse(JSON.stringify(d));

// ---------------------------------------------------------------- Validation
const plain=v=>!!v&&typeof v==='object'&&!Array.isArray(v)&&Object.getPrototypeOf(v)===Object.prototype;
const CONSTRAINT_CHECKS={'deadline-order':p=>p.priorityDeadline<=p.standardDeadline,'income-shares':p=>p.lowIncomeSharePct+p.highIncomeSharePct<=100};
function checkParam(def,value,errors,field) {
 if(def.type==='bool'){if(typeof value!=='boolean')errors.push({field,message:`${def.label} must be on or off.`});return;}
 if(!Number.isSafeInteger(value)||value<def.min||value>def.max)errors.push({field,message:`${def.label} must be a whole number from ${def.min} to ${def.max}.`});
}
/** Fill defaults for omitted keys; reject unknown keys and out-of-range values. */
export function validateParams(schema,input,errors,prefix) {
 if(input!==undefined&&!plain(input)){errors.push({field:prefix,message:'Parameters must be an object of named values.'});return {};}
 const out={};
 for(const key of Object.keys(input??{}))if(!schema.some(d=>d.id===key))errors.push({field:`${prefix}.${key}`,message:`Unknown parameter “${String(key).slice(0,40)}”.`});
 for(const def of schema){const value=input?.[def.id]===undefined?def.default:input[def.id];checkParam(def,value,errors,`${prefix}.${def.id}`);out[def.id]=value;}
 return out;
}
export function scenarioConstraintErrors(scenario,params) {
 return scenario.constraints.filter(c=>!CONSTRAINT_CHECKS[c.id](params)).map(c=>({field:'params',message:c.message}));
}
const PLAN_KEYS=['scenario','version','params','policies','baseSeed','replications','sweep','weights','label'];
const cleanLabel=s=>s.replace(/[\u0000-\u001f\u007f<>`]/g,'').replace(/\s+/g,' ').trim();
/**
 * Validates an experiment plan exactly as the server will execute it. Returns the normalized plan with
 * explicit defaults, policy versions and the replication seed list, or a list of field errors.
 */
export function validatePlan(input) {
 const errors=[],L=SANDBOX_LIMITS;
 if(!plain(input))return {ok:false,errors:[{field:'plan',message:'The experiment plan must be an object.'}]};
 for(const key of Object.keys(input))if(!PLAN_KEYS.includes(key))errors.push({field:String(key).slice(0,40),message:'Unknown plan field.'});
 const scenario=typeof input.scenario==='string'&&Number.isSafeInteger(input.version)?scenarioFor(input.scenario,input.version):null;
 if(!scenario)return {ok:false,errors:[...errors,{field:'scenario',message:'Choose a registered scenario and version. Refresh the workstation if the lab was updated.'}]};
 const params=validateParams(scenario.params,input.params,errors,'params');
 if(!errors.length)errors.push(...scenarioConstraintErrors(scenario,params));
 const policies=[];
 if(!Array.isArray(input.policies)||input.policies.length<L.minPolicies||input.policies.length>L.maxPolicies)errors.push({field:'policies',message:`Select ${L.minPolicies} to ${L.maxPolicies} policies to compare.`});
 else input.policies.forEach((p,i)=>{
  if(!plain(p)||typeof p.id!=='string'||!scenario.policies.includes(p.id)||Object.keys(p).some(k=>!['id','version','params'].includes(k))){errors.push({field:`policies.${i}`,message:'Choose a policy registered for this scenario.'});return;}
  const def=p.version===undefined?latestPolicy(p.id):SANDBOX_POLICIES[policyKey(p.id,p.version)];
  if(!def||def.domain!==scenario.domain){errors.push({field:`policies.${i}`,message:'That policy version is not available.'});return;}
  policies.push({key:`P${i+1}`,id:def.id,version:def.version,params:validateParams(def.params,p.params,errors,`policies.${i}.params`)});
 });
 const signature=p=>JSON.stringify([p.id,p.version,p.params]);
 if(new Set(policies.map(signature)).size!==policies.length)errors.push({field:'policies',message:'Each compared policy must differ in its rule or parameters.'});
 const baseSeed=input.baseSeed;
 if(!Number.isSafeInteger(baseSeed)||baseSeed<0||baseSeed>L.maxSeed)errors.push({field:'baseSeed',message:`Choose a seed from 0 to ${L.maxSeed}.`});
 const replications=input.replications??1;
 if(!Number.isSafeInteger(replications)||replications<1||replications>L.maxReplications)errors.push({field:'replications',message:`Choose 1 to ${L.maxReplications} replications.`});
 let sweep=null;
 if(input.sweep!==undefined&&input.sweep!==null) {
  const def=plain(input.sweep)&&scenario.params.find(d=>d.id===input.sweep.param&&d.sweep);
  if(!def||!Array.isArray(input.sweep.values)||input.sweep.values.length<2||input.sweep.values.length>L.maxSweepValues||Object.keys(input.sweep).some(k=>!['param','values'].includes(k)))errors.push({field:'sweep',message:`Choose a sweepable parameter and 2 to ${L.maxSweepValues} values.`});
  else {
   input.sweep.values.forEach((v,i)=>checkParam(def,v,errors,`sweep.values.${i}`));
   if(new Set(input.sweep.values).size!==input.sweep.values.length)errors.push({field:'sweep',message:'Sensitivity values must be different.'});
   for(const v of input.sweep.values)if(!errors.length)for(const e of scenarioConstraintErrors(scenario,{...params,[def.id]:v}))errors.push({...e,field:'sweep'});
   sweep={param:def.id,values:[...input.sweep.values]};
  }
 }
 const weights={};
 if(input.weights!==undefined&&input.weights!==null) {
  if(!plain(input.weights))errors.push({field:'weights',message:'Weights must map objective metrics to whole numbers.'});
  else for(const [k,v] of Object.entries(input.weights)) {
   if(!scenario.objectives.includes(k))errors.push({field:`weights.${String(k).slice(0,40)}`,message:'Weights can only be set for this scenario’s objective metrics.'});
   else if(!Number.isSafeInteger(v)||v<0||v>L.weightMax)errors.push({field:`weights.${k}`,message:`Weights must be whole numbers from 0 to ${L.weightMax}.`});
   else if(v>0)weights[k]=v;
  }
 }
 const label=input.label===undefined?'':typeof input.label==='string'&&input.label.length<=L.labelLength*2?cleanLabel(input.label).slice(0,L.labelLength):null;
 if(label===null)errors.push({field:'label',message:`Labels are at most ${L.labelLength} characters.`});
 const conditions=sweep?sweep.values.length:1,runs=conditions*(Number.isSafeInteger(replications)?replications:1)*policies.length;
 if(runs>L.maxRuns)errors.push({field:'replications',message:`This plan needs ${runs} runs; the limit is ${L.maxRuns}. Reduce replications, policies or sensitivity values.`});
 if(errors.length)return {ok:false,errors:errors.slice(0,12)};
 const seeds=Array.from({length:replications},(_,i)=>(baseSeed+i)%(L.maxSeed+1));
 return {ok:true,plan:{scenario:scenario.id,version:scenario.version,params,policies,baseSeed,replications,seeds,sweep,weights,label},runs};
}
/** Effective parameters for each sensitivity condition. */
export const conditionsFor=plan=>plan.sweep?plan.sweep.values.map((v,i)=>({index:i,label:`${plan.sweep.param} = ${v}`,params:{...plan.params,[plan.sweep.param]:v}})):[{index:0,label:'Configured parameters',params:{...plan.params}}];
export function policyLabel(p) {
 const def=SANDBOX_POLICIES[policyKey(p.id,p.version)],changed=def?.params.filter(d=>p.params[d.id]!==d.default)??[];
 return `${def?.name??p.id}${changed.length?` (${changed.map(d=>`${d.label.toLowerCase()} ${typeof p.params[d.id]==='boolean'?(p.params[d.id]?'on':'off'):p.params[d.id]}`).join(', ')})`:''}`;
}
